// ============================================================================
// Phase 2 Enhanced: SQLite3 Persistent Database
// ============================================================================

const Database = require('better-sqlite3');
const path = require('path');
const crypto = require('crypto');

const DB_PATH = path.join(__dirname, '../../db/blogs.db');

let db = null;

function initializeDB() {
  try {
    db = new Database(DB_PATH);
    db.pragma('journal_mode = WAL');
    db.pragma('synchronous = NORMAL');
    db.pragma('foreign_keys = ON');

    db.exec(`
      CREATE TABLE IF NOT EXISTS blogs (
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        content TEXT NOT NULL,
        author TEXT NOT NULL,
        createdAt TEXT NOT NULL,
        updatedAt TEXT NOT NULL,
        views INTEGER DEFAULT 0,
        version INTEGER DEFAULT 1,
        deleted INTEGER DEFAULT 0,
        status TEXT DEFAULT 'draft',
        tags TEXT
      );

      CREATE INDEX IF NOT EXISTS idx_author ON blogs(author);
      CREATE INDEX IF NOT EXISTS idx_status ON blogs(status);
      CREATE INDEX IF NOT EXISTS idx_deleted ON blogs(deleted);
    `);

    console.log(`✅ SQLite3 initialized: ${DB_PATH}`);
    return true;
  } catch (err) {
    console.error('❌ SQLite3 init failed:', err.message);
    return false;
  }
}

function connect() {
  if (!db) initializeDB();
  return {
    insert: insertBlog,
    get: getBlog,
    getAll: getAllBlogs,
    update: updateBlog,
    delete: deleteBlog,
    search: searchBlogs,
    stats: getStats,
    backup: backupDatabase,
    migrate: migrateFromJSON
  };
}

function insertBlog(blog) {
  try {
    const stmt = db.prepare(`
      INSERT INTO blogs (id, title, content, author, createdAt, updatedAt, version, status)
      VALUES (?, ?, ?, ?, ?, ?, 1, ?)
    `);

    const blogId = blog.id || generateId();
    const now = new Date().toISOString();

    stmt.run(
      blogId,
      blog.title || 'Untitled',
      blog.content || '',
      blog.author || 'Unknown',
      blog.createdAt || now,
      blog.updatedAt || now,
      blog.status || 'draft'
    );

    console.log(`✅ Blog inserted: ${blogId}`);
    return { success: true, id: blogId };
  } catch (err) {
    console.error('❌ Insert failed:', err.message);
    return { success: false, error: err.message };
  }
}

function getBlog(blogId) {
  try {
    const stmt = db.prepare(`
      SELECT * FROM blogs WHERE id = ? AND deleted = 0
    `);

    const blog = stmt.get(blogId);
    if (blog) {
      // Increment views
      db.prepare(`UPDATE blogs SET views = views + 1 WHERE id = ?`).run(blogId);
      return { success: true, data: blog };
    }
    return { success: false, error: 'Not found' };
  } catch (err) {
    console.error('❌ Get failed:', err.message);
    return { success: false, error: err.message };
  }
}

function getAllBlogs(limit = 100, offset = 0) {
  try {
    const stmt = db.prepare(`
      SELECT * FROM blogs WHERE deleted = 0 ORDER BY createdAt DESC LIMIT ? OFFSET ?
    `);

    const blogs = stmt.all(limit, offset);
    const count = db.prepare(`SELECT COUNT(*) as c FROM blogs WHERE deleted = 0`).get().c;

    return { success: true, data: blogs, total: count };
  } catch (err) {
    console.error('❌ GetAll failed:', err.message);
    return { success: false, error: err.message };
  }
}

function updateBlog(blogId, updates) {
  try {
    const blog = db.prepare(`SELECT * FROM blogs WHERE id = ?`).get(blogId);
    if (!blog) return { success: false, error: 'Not found' };

    if (updates.version && updates.version !== blog.version) {
      return { success: false, error: 'Version conflict' };
    }

    const stmt = db.prepare(`
      UPDATE blogs SET
        title = COALESCE(?, title),
        content = COALESCE(?, content),
        author = COALESCE(?, author),
        status = COALESCE(?, status),
        updatedAt = ?,
        version = ?
      WHERE id = ?
    `);

    stmt.run(
      updates.title || null,
      updates.content || null,
      updates.author || null,
      updates.status || null,
      new Date().toISOString(),
      (blog.version || 0) + 1,
      blogId
    );

    console.log(`✅ Blog updated: ${blogId}`);
    return { success: true, version: (blog.version || 0) + 1 };
