// ============================================================================
// Phase 2 Enhanced: SQLite3 Persistent Database
// ============================================================================

const Database = require('better-sqlite3');
const path = require('path');
const crypto = require('crypto');

const DB_PATH = path.join(__dirname, '../../db/blogs.db');

let db = null;

function initializeDB() {
  try {
    db = new Database(DB_PATH);
    db.pragma('journal_mode = WAL');
    db.pragma('synchronous = NORMAL');
    db.pragma('foreign_keys = ON');

    db.exec(`
      CREATE TABLE IF NOT EXISTS blogs (
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        content TEXT NOT NULL,
        author TEXT NOT NULL,
        createdAt TEXT NOT NULL,
        updatedAt TEXT NOT NULL,
        views INTEGER DEFAULT 0,
        version INTEGER DEFAULT 1,
        deleted INTEGER DEFAULT 0,
        status TEXT DEFAULT 'draft',
        tags TEXT
      );

      CREATE INDEX IF NOT EXISTS idx_author ON blogs(author);
      CREATE INDEX IF NOT EXISTS idx_status ON blogs(status);
      CREATE INDEX IF NOT EXISTS idx_deleted ON blogs(deleted);
    `);

    console.log(`✅ SQLite3 initialized: ${DB_PATH}`);
    return true;
  } catch (err) {
    console.error('❌ SQLite3 init failed:', err.message);
    return false;
  }
}

function connect() {
  if (!db) initializeDB();
  return {
    insert: insertBlog,
    get: getBlog,
    getAll: getAllBlogs,
    update: updateBlog,
    delete: deleteBlog,
    search: searchBlogs,
    stats: getStats,
    backup: backupDatabase,
    migrate: migrateFromJSON
  };
}

