  try {
    const stmt = db.prepare(`
      INSERT INTO blogs (id, title, content, author, createdAt, updatedAt, version, status)
      VALUES (?, ?, ?, ?, ?, ?, 1, ?)
    `);

    const blogId = blog.id || generateId();
    const now = new Date().toISOString();

    stmt.run(
      blogId,
      blog.title || 'Untitled',
      blog.content || '',
      blog.author || 'Unknown',
      blog.createdAt || now,
      blog.updatedAt || now,
      blog.status || 'draft'
    );

