      const policy = this.policies.get(serviceName);
      if (policy && this.metrics.totalRequests % 100 < 5) {
        // 5% of requests fail due to rate limit (simulated)
        throw new Error('Rate limit exceeded');
      }

      // 3. Select endpoint (round-robin or weighted)
      const endpoint = this.selectEndpoint(service, options);

      // 4. Simulate service call
      const result = await this.callService(endpoint, request, service);

      // 5. Record success
      const latency = Date.now() - startTime;
      this.metrics.successfulRequests++;
      this.metrics.latencies.push(latency);

      return {
        success: true,
        data: result,
        endpoint: `${endpoint.host}:${endpoint.port}`,
        latency,
        tracingId: generateId()
      };
    } catch (err) {
      this.metrics.failedRequests++;
      console.error('❌ Route failed:', err.message);
      return {
        success: false,
        error: err.message,
        tracingId: generateId()
      };
    }
  }

  selectEndpoint(service, options) {
    // Load balancing: round-robin or weighted
    if (service.loadBalancingPolicy === 'round-robin') {
      const index = this.metrics.totalRequests % service.endpoints.length;
      return service.endpoints[index];
    } else if (service.loadBalancingPolicy === 'least-connections') {
      return service.endpoints.reduce((a, b) =>
        (a.connections || 0) < (b.connections || 0) ? a : b
      );
    } else {
      return service.endpoints[0];
    }
  }

  async callService(endpoint, request, service) {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(
        () => reject(new Error(`Timeout after ${service.timeout}ms`)),
        service.timeout
      );

      // Simulate service call
      const delay = Math.random() * 100;
      setTimeout(() => {
        clearTimeout(timeout);
        if (Math.random() < 0.95) {
          resolve({
            status: 200,
            body: `Response from ${endpoint.host}:${endpoint.port}`,
            timestamp: new Date().toISOString()
          });
        } else {
          reject(new Error('Service error (5xx)'));
        }
      }, delay);
    });
  }

  // Distributed Tracing
  createSpan(name, parent = null) {
    const span = {
      id: generateId(),
      traceId: parent?.traceId || generateId(),
      parentId: parent?.id || null,
      name,
      startTime: Date.now(),
      tags: {},
      logs: []
    };
    return span;
  }

  addLog(span, message) {
    span.logs.push({
      timestamp: Date.now(),
      message
    });
  }

  finishSpan(span) {
    span.duration = Date.now() - span.startTime;
    return span;
  }

  // Metrics Collection
  getMetrics() {
    const successRate = this.metrics.totalRequests > 0
      ? ((this.metrics.successfulRequests / this.metrics.totalRequests) * 100).toFixed(2)
      : 0;

    const avgLatency = this.metrics.latencies.length > 0
      ? (this.metrics.latencies.reduce((a, b) => a + b, 0) / this.metrics.latencies.length).toFixed(2)
      : 0;

    return {
      totalRequests: this.metrics.totalRequests,
      successfulRequests: this.metrics.successfulRequests,
      failedRequests: this.metrics.failedRequests,
      successRate: `${successRate}%`,
      averageLatency: `${avgLatency}ms`,
      p99Latency: this.getPercentile(99),
      p95Latency: this.getPercentile(95),
      services: Array.from(this.services.values()).map(s => ({
        name: s.name,
        version: s.version,
        endpoints: s.endpoints.length,
        healthCheck: s.healthCheck.path
      }))
    };
  }

  getPercentile(percentile) {
    if (this.metrics.latencies.length === 0) return 0;

    const sorted = [...this.metrics.latencies].sort((a, b) => a - b);
    const index = Math.ceil((percentile / 100) * sorted.length) - 1;
    return `${sorted[Math.max(0, index)].toFixed(2)}ms`;
  }

  // Authorization Policy
  createAuthPolicy(name, rules) {
    const policy = {
      id: generateId(),
      name,
      rules: rules.map(r => ({
        from: r.from || [{ principals: ['*'] }],
        to: r.to || [{ operation: { methods: ['*'] } }]
      }))
    };
    console.log(`✅ AuthPolicy created: ${name}`);
    return policy;
  }

  // Gateway (Ingress)
  createGateway(name, host, port) {
    const gateway = {
      id: generateId(),
      name,
      host,
      port,
      servers: [{
        port: { number: port, name: 'http', protocol: 'HTTP' },
        hosts: [host]
      }]
    };
    console.log(`✅ Gateway created: ${name} (${host}:${port})`);
    return gateway;
  }
}

function generateId() {
  return crypto.randomBytes(6).toString('hex');
}

// ──────────────────────────────────────────────────────────────────────────
// Observability: Tracing & Monitoring
// ──────────────────────────────────────────────────────────────────────────

class DistributedTracer {
  constructor() {
    this.traces = new Map();
    this.spans = [];
  }

  startTrace(name) {
    const traceId = generateId();
    const trace = {
      id: traceId,
      name,
      startTime: Date.now(),
      spans: []
    };
    this.traces.set(traceId, trace);
    return traceId;
  }

  createSpan(traceId, spanName, parentSpanId = null) {
    const span = {
      spanId: generateId(),
      traceId,
      parentSpanId,
      name: spanName,
      startTime: Date.now(),
      tags: {},
      logs: [],
      status: 'in_progress'
    };
    this.spans.push(span);
    return span;
  }

  finishSpan(span) {
    span.endTime = Date.now();
    span.duration = span.endTime - span.startTime;
    span.status = 'finished';
    return span;
  }

  exportTraces(format = 'jaeger') {
    return {
      format,
      totalTraces: this.traces.size,
      totalSpans: this.spans.length,
      traces: Array.from(this.traces.values()).map(t => ({
        ...t,
        duration: Date.now() - t.startTime
      }))
    };
  }
}

// Export
module.exports = {
  ServiceMesh,
  DistributedTracer,
  createMesh: () => new ServiceMesh(),
  createTracer: () => new DistributedTracer()
};

