// ============================================================================
// Phase 3 New: Prometheus Metrics & Monitoring
// ============================================================================

// Prometheus metrics in Prometheus text format

class MetricsCollector {
  constructor() {
    this.metrics = new Map();
    this.timestamp = Date.now();
    this.initializeMetrics();
  }

  initializeMetrics() {
    // Counter metrics
    this.registerCounter('http_requests_total', 'Total HTTP requests');
    this.registerCounter('http_requests_success', 'Successful HTTP requests');
    this.registerCounter('http_requests_failed', 'Failed HTTP requests');
    this.registerCounter('database_operations_total', 'Total DB operations');
    this.registerCounter('database_errors_total', 'DB operation errors');

    // Gauge metrics
    this.registerGauge('http_request_duration_ms', 'HTTP request duration');
    this.registerGauge('database_connection_active', 'Active DB connections');
    this.registerGauge('service_health_status', 'Service health status (1=healthy, 0=unhealthy)');
    this.registerGauge('memory_usage_bytes', 'Memory usage in bytes');

    // Histogram metrics
    this.registerHistogram('http_response_time_seconds', 'HTTP response time', [0.1, 0.5, 1.0, 2.0, 5.0]);
    this.registerHistogram('database_query_duration_seconds', 'DB query duration', [0.01, 0.05, 0.1, 0.5, 1.0]);
  }

  registerCounter(name, help, labels = {}) {
    this.metrics.set(name, {
      type: 'counter',
      help,
      labels,
      value: 0
    });
  }

  registerGauge(name, help, labels = {}) {
    this.metrics.set(name, {
      type: 'gauge',
      help,
      labels,
      value: 0
    });
  }

  registerHistogram(name, help, buckets) {
    this.metrics.set(name, {
      type: 'histogram',
      help,
      buckets,
      values: []
    });
  }

  // Record metrics
  recordRequest(method, status, duration) {
    this.incrementCounter('http_requests_total');

    if (status >= 200 && status < 300) {
      this.incrementCounter('http_requests_success');
    } else {
      this.incrementCounter('http_requests_failed');
    }

    this.recordHistogram('http_response_time_seconds', duration / 1000);
  }

  recordDatabaseOperation(operation, success, duration) {
    this.incrementCounter('database_operations_total');

    if (!success) {
      this.incrementCounter('database_errors_total');
    }

    this.recordHistogram('database_query_duration_seconds', duration / 1000);
  }

  recordServiceHealth(serviceName, healthy) {
    this.setGauge('service_health_status', healthy ? 1 : 0);
  }

  recordMemory(bytes) {
    this.setGauge('memory_usage_bytes', bytes);
  }

  recordDatabaseConnection(count) {
    this.setGauge('database_connection_active', count);
  }

  // Helper methods
  incrementCounter(name, value = 1) {
    const metric = this.metrics.get(name);
    if (metric && metric.type === 'counter') {
      metric.value += value;
    }
  }

  setGauge(name, value) {
    const metric = this.metrics.get(name);
    if (metric && metric.type === 'gauge') {
      metric.value = value;
    }
  }

  recordHistogram(name, value) {
    const metric = this.metrics.get(name);
    if (metric && metric.type === 'histogram') {
      metric.values.push(value);
      // Keep last 1000 values
      if (metric.values.length > 1000) {
        metric.values.shift();
      }
    }
  }

  // Export metrics in Prometheus format
  exportPrometheus() {
    let output = '';

    for (const [name, metric] of this.metrics) {
      // Add HELP line
      output += `# HELP ${name} ${metric.help}\n`;

      if (metric.type === 'counter') {
        output += `# TYPE ${name} counter\n`;
        output += `${name} ${metric.value}\n\n`;
      } else if (metric.type === 'gauge') {
        output += `# TYPE ${name} gauge\n`;
        output += `${name} ${metric.value}\n\n`;
      } else if (metric.type === 'histogram') {
        output += `# TYPE ${name} histogram\n`;

        // Calculate percentiles
        const sorted = [...metric.values].sort((a, b) => a - b);

        for (const bucket of metric.buckets) {
          const count = sorted.filter(v => v <= bucket).length;
          output += `${name}_bucket{le="${bucket}"} ${count}\n`;
        }

        output += `${name}_bucket{le="+Inf"} ${metric.values.length}\n`;
        output += `${name}_sum ${metric.values.reduce((a, b) => a + b, 0).toFixed(6)}\n`;
        output += `${name}_count ${metric.values.length}\n\n`;
      }
    }

    return output;
  }

  // Get metrics as JSON
  exportJSON() {
    const result = {
      timestamp: Date.now(),
      uptime: Date.now() - this.timestamp,
      metrics: {}
    };

    for (const [name, metric] of this.metrics) {
      if (metric.type === 'histogram') {
        result.metrics[name] = {
          type: 'histogram',
          count: metric.values.length,
          sum: metric.values.reduce((a, b) => a + b, 0),
          min: Math.min(...metric.values),
          max: Math.max(...metric.values),
          avg: metric.values.reduce((a, b) => a + b, 0) / metric.values.length || 0,
          p50: this.getPercentile(metric.values, 50),
          p95: this.getPercentile(metric.values, 95),
          p99: this.getPercentile(metric.values, 99)
        };
      } else {
        result.metrics[name] = {
          type: metric.type,
          value: metric.value
        };
      }
    }

    return result;
  }

  getPercentile(values, percentile) {
    if (values.length === 0) return 0;
    const sorted = [...values].sort((a, b) => a - b);
    const index = Math.ceil((percentile / 100) * sorted.length) - 1;
    return sorted[Math.max(0, index)];
  }

  // Get dashboard summary
  getDashboard() {
    return {
      httpMetrics: {
        totalRequests: this.metrics.get('http_requests_total')?.value || 0,
        successfulRequests: this.metrics.get('http_requests_success')?.value || 0,
        failedRequests: this.metrics.get('http_requests_failed')?.value || 0,
        successRate: this.getSuccessRate()
      },
      databaseMetrics: {
        totalOperations: this.metrics.get('database_operations_total')?.value || 0,
        errors: this.metrics.get('database_errors_total')?.value || 0,
        activeConnections: this.metrics.get('database_connection_active')?.value || 0
      },
      systemMetrics: {
        memoryUsage: `${(this.metrics.get('memory_usage_bytes')?.value || 0) / 1024 / 1024}MB`,
        uptime: this.getUptime()
      },
      latency: this.getLatencyStats()
    };
  }

  getSuccessRate() {
    const total = this.metrics.get('http_requests_total')?.value || 0;
    const success = this.metrics.get('http_requests_success')?.value || 0;
    return total > 0 ? ((success / total) * 100).toFixed(2) + '%' : 'N/A';
  }

  getUptime() {
    const uptime = Date.now() - this.timestamp;
    const hours = Math.floor(uptime / 3600000);
    const minutes = Math.floor((uptime % 3600000) / 60000);
    return `${hours}h ${minutes}m`;
  }

  getLatencyStats() {
    const responseTimeMetric = this.metrics.get('http_response_time_seconds');
    if (!responseTimeMetric || responseTimeMetric.values.length === 0) {
      return { avg: 0, p50: 0, p95: 0, p99: 0 };
    }

    const values = responseTimeMetric.values;
    return {
      avg: (values.reduce((a, b) => a + b, 0) / values.length).toFixed(3) + 's',
      p50: this.getPercentile(values, 50).toFixed(3) + 's',
      p95: this.getPercentile(values, 95).toFixed(3) + 's',
      p99: this.getPercentile(values, 99).toFixed(3) + 's'
    };
  }

  // Alert rules
  checkAlerts() {
    const alerts = [];

    const successRate = this.metrics.get('http_requests_success')?.value || 0;
    const totalRequests = this.metrics.get('http_requests_total')?.value || 1;
    const rate = (successRate / totalRequests) * 100;

    if (rate < 90) {
      alerts.push({
        severity: 'warning',
        message: `Low success rate: ${rate.toFixed(2)}%`
      });
    }

    const dbErrors = this.metrics.get('database_errors_total')?.value || 0;
    if (dbErrors > 10) {
      alerts.push({
        severity: 'critical',
        message: `High DB error count: ${dbErrors}`
      });
    }

    return alerts;
  }
}

// ──────────────────────────────────────────────────────────────────────────
// Real-time Dashboard
// ──────────────────────────────────────────────────────────────────────────

class Dashboard {
  constructor(metricsCollector) {
    this.collector = metricsCollector;
    this.updateInterval = 5000;
  }

  render() {
    const dashboard = this.collector.getDashboard();
    const alerts = this.collector.checkAlerts();

    console.log('\n╔════════════════════════════════════════════════════════╗');
    console.log('║          📊 Real-time Monitoring Dashboard            ║');
    console.log('╚════════════════════════════════════════════════════════╝\n');

    console.log('🌐 HTTP Metrics:');
    console.log(`   Total Requests: ${dashboard.httpMetrics.totalRequests}`);
    console.log(`   Successful: ${dashboard.httpMetrics.successfulRequests}`);
    console.log(`   Failed: ${dashboard.httpMetrics.failedRequests}`);
    console.log(`   Success Rate: ${dashboard.httpMetrics.successRate}`);

    console.log('\n🗄️  Database Metrics:');
    console.log(`   Total Operations: ${dashboard.databaseMetrics.totalOperations}`);
    console.log(`   Errors: ${dashboard.databaseMetrics.errors}`);
    console.log(`   Active Connections: ${dashboard.databaseMetrics.activeConnections}`);

    console.log('\n⚙️  System Metrics:');
    console.log(`   Memory Usage: ${dashboard.systemMetrics.memoryUsage}`);
    console.log(`   Uptime: ${dashboard.systemMetrics.uptime}`);

    console.log('\n⏱️  Latency:');
    console.log(`   Avg: ${dashboard.latency.avg}`);
    console.log(`   p50: ${dashboard.latency.p50}`);
    console.log(`   p95: ${dashboard.latency.p95}`);
    console.log(`   p99: ${dashboard.latency.p99}`);

    if (alerts.length > 0) {
      console.log('\n🚨 Alerts:');
      alerts.forEach(alert => {
        console.log(`   [${alert.severity.toUpperCase()}] ${alert.message}`);
      });
    }
  }
}

// Export
module.exports = {
  MetricsCollector,
  Dashboard,
  createCollector: () => new MetricsCollector(),
  createDashboard: (collector) => new Dashboard(collector)
};

