// ============================================================================
// Phase 5 New: Dynamic Autoscaling & Load Management
// ============================================================================

const crypto = require('crypto');

class AutoScaler {
  constructor(options = {}) {
    this.minInstances = options.minInstances || 2;
    this.maxInstances = options.maxInstances || 10;
    this.targetCPU = options.targetCPU || 70;  // 70% CPU target
    this.targetMemory = options.targetMemory || 80;
    this.scaleUpThreshold = options.scaleUpThreshold || 3;  // Seconds above threshold
    this.scaleDownThreshold = options.scaleDownThreshold || 10;

    this.instances = [];
    this.metrics = [];
    this.decisions = [];
    this.scaleCounter = 0;
    this.lastScaleAction = Date.now();

    this.initialize();
  }

  initialize() {
    // Create minimum instances
    for (let i = 0; i < this.minInstances; i++) {
      this.addInstance();
    }
    console.log(`✅ Autoscaler initialized with ${this.minInstances} instances`);
  }

  addInstance() {
    const instance = {
      id: generateId(),
      status: 'running',
      createdAt: Date.now(),
      cpu: 0,
      memory: 0,
      requests: 0,
      errors: 0,
      lastHealthCheck: Date.now()
    };
    this.instances.push(instance);
    console.log(`✅ Instance added: ${instance.id}`);
    return instance.id;
  }

  removeInstance(instanceId) {
    const idx = this.instances.findIndex(i => i.id === instanceId);
    if (idx >= 0) {
      this.instances.splice(idx, 1);
      console.log(`✅ Instance removed: ${instanceId}`);
      return true;
    }
    return false;
  }

  // Update instance metrics
  updateMetrics(instanceId, metrics) {
    const instance = this.instances.find(i => i.id === instanceId);
    if (instance) {
      instance.cpu = metrics.cpu || 0;
      instance.memory = metrics.memory || 0;
      instance.requests = (instance.requests || 0) + (metrics.newRequests || 0);
      instance.errors = (instance.errors || 0) + (metrics.newErrors || 0);
      instance.lastHealthCheck = Date.now();

      this.metrics.push({
        timestamp: Date.now(),
        instanceId,
        cpu: instance.cpu,
        memory: instance.memory
      });

      // Keep last 1000 metrics
      if (this.metrics.length > 1000) {
        this.metrics.shift();
      }
    }
  }

  // Main scaling decision algorithm
  makeScalingDecision() {
    const avgCPU = this.getAverageCPU();
    const avgMemory = this.getAverageMemory();
    const currentInstanceCount = this.instances.length;

    const decision = {
      timestamp: Date.now(),
      currentInstances: currentInstanceCount,
      avgCPU,
      avgMemory,
      action: 'none',
      reason: ''
    };

    // Scale UP: CPU or Memory above threshold
    if (avgCPU > this.targetCPU || avgMemory > this.targetMemory) {
      this.scaleCounter++;

      if (this.scaleCounter >= this.scaleUpThreshold && currentInstanceCount < this.maxInstances) {
        const newCount = Math.min(currentInstanceCount + 1, this.maxInstances);
        decision.action = 'scale_up';
        decision.reason = `CPU: ${avgCPU}%, Memory: ${avgMemory}%`;
        decision.newInstances = newCount;

        this.addInstance();
        this.scaleCounter = 0;
        this.lastScaleAction = Date.now();

        console.log(`📈 SCALE UP: ${currentInstanceCount} → ${newCount} instances`);
      }
    }
    // Scale DOWN: CPU and Memory below 30%
    else if (avgCPU < 30 && avgMemory < 30) {
      this.scaleCounter--;

      if (this.scaleCounter <= -this.scaleDownThreshold && currentInstanceCount > this.minInstances) {
        const newCount = Math.max(currentInstanceCount - 1, this.minInstances);
        decision.action = 'scale_down';
        decision.reason = `Low utilization: CPU ${avgCPU}%, Memory ${avgMemory}%`;
        decision.newInstances = newCount;

        // Find least utilized instance to remove
        const instanceToRemove = this.instances.reduce((a, b) =>
          (a.cpu + a.memory) < (b.cpu + b.memory) ? a : b
        );

        this.removeInstance(instanceToRemove.id);
        this.scaleCounter = 0;
        this.lastScaleAction = Date.now();

        console.log(`📉 SCALE DOWN: ${currentInstanceCount} → ${newCount} instances`);
      }
    } else {
      this.scaleCounter = 0;
    }

    this.decisions.push(decision);

    // Keep last 1000 decisions
    if (this.decisions.length > 1000) {
      this.decisions.shift();
    }

    return decision;
  }

  getAverageCPU() {
    if (this.instances.length === 0) return 0;
    const sum = this.instances.reduce((a, b) => a + (b.cpu || 0), 0);
    return Math.round(sum / this.instances.length);
  }

  getAverageMemory() {
    if (this.instances.length === 0) return 0;
    const sum = this.instances.reduce((a, b) => a + (b.memory || 0), 0);
    return Math.round(sum / this.instances.length);
  }

  // Health check for failed instances
  healthCheck() {
    const now = Date.now();
    const healthyInstances = [];
    const unhealthyInstances = [];

    this.instances.forEach(instance => {
      const timeSinceCheck = now - instance.lastHealthCheck;

      // Instance is unhealthy if not checked in 30 seconds
      if (timeSinceCheck > 30000) {
        unhealthyInstances.push(instance);
      } else {
        healthyInstances.push(instance);
      }
    });

    // Replace unhealthy instances
    unhealthyInstances.forEach(instance => {
      console.log(`⚠️ Unhealthy instance detected: ${instance.id}`);
      this.removeInstance(instance.id);
      if (this.instances.length < this.minInstances) {
        this.addInstance();
        console.log(`✅ Replacement instance created`);
      }
    });

    return {
      total: this.instances.length,
      healthy: healthyInstances.length,
      unhealthy: unhealthyInstances.length
    };
  }

  // Pod Disruption Budget (PDB) - graceful shutdown
  gracefulShutdown(instanceId, gracePeriod = 30000) {
    const instance = this.instances.find(i => i.id === instanceId);
    if (!instance) return false;

    instance.status = 'draining';

    return new Promise((resolve) => {
      setTimeout(() => {
        this.removeInstance(instanceId);
        resolve(true);
      }, gracePeriod);
    });
  }

  // Metrics export
  getMetrics() {
    return {
      timestamp: Date.now(),
      currentInstances: this.instances.length,
      minInstances: this.minInstances,
      maxInstances: this.maxInstances,
      averageCPU: this.getAverageCPU(),
      averageMemory: this.getAverageMemory(),
      targetCPU: this.targetCPU,
      targetMemory: this.targetMemory,
      instances: this.instances.map(i => ({
        id: i.id,
        status: i.status,
        cpu: i.cpu,
        memory: i.memory,
        requests: i.requests,
        errors: i.errors,
        uptime: Math.floor((Date.now() - i.createdAt) / 1000)
      })),
      recentDecisions: this.decisions.slice(-10)
    };
  }
}

// ──────────────────────────────────────────────────────────────────────────
// Horizontal Pod Autoscaler (HPA) Simulator
// ──────────────────────────────────────────────────────────────────────────

class HorizontalPodAutoscaler {
  constructor(deployment, metrics, options = {}) {
    this.deployment = deployment;
    this.metrics = metrics;
    this.minReplicas = options.minReplicas || 1;
    this.maxReplicas = options.maxReplicas || 10;
    this.targetUtilization = options.targetUtilization || 70;
    this.scaleUpCooldown = options.scaleUpCooldown || 60000;  // 60s
    this.scaleDownCooldown = options.scaleDownCooldown || 300000;  // 5min
    this.lastScaleUp = 0;
    this.lastScaleDown = 0;
  }

  calculateReplicas() {
    const currentReplicas = this.deployment.replicas;
    const currentUtilization = this.deployment.metrics.cpu || 0;

    let desiredReplicas = currentReplicas;

    if (currentUtilization > this.targetUtilization) {
      // Scale up
      const now = Date.now();
      if (now - this.lastScaleUp > this.scaleUpCooldown) {
        desiredReplicas = Math.ceil(
          (currentReplicas * currentUtilization) / this.targetUtilization
        );
        desiredReplicas = Math.min(desiredReplicas, this.maxReplicas);
        this.lastScaleUp = now;
      }
    } else if (currentUtilization < this.targetUtilization * 0.5) {
      // Scale down
      const now = Date.now();
      if (now - this.lastScaleDown > this.scaleDownCooldown) {
        desiredReplicas = Math.max(
          Math.floor((currentReplicas * currentUtilization) / this.targetUtilization),
          this.minReplicas
        );
        this.lastScaleDown = now;
      }
    }

    return Math.max(this.minReplicas, Math.min(desiredReplicas, this.maxReplicas));
  }

  status() {
    return {
      deployment: this.deployment.name,
      currentReplicas: this.deployment.replicas,
      desiredReplicas: this.calculateReplicas(),
      minReplicas: this.minReplicas,
      maxReplicas: this.maxReplicas,
      currentUtilization: this.deployment.metrics.cpu,
      targetUtilization: this.targetUtilization
    };
  }
}

// ──────────────────────────────────────────────────────────────────────────
// Resource Quota & Limits
// ──────────────────────────────────────────────────────────────────────────

class ResourceQuota {
  constructor(options = {}) {
    this.limits = {
      cpuTotal: options.cpuTotal || 4000,  // millicores
      memoryTotal: options.memoryTotal || 8192,  // MB
      requestsPerSecond: options.rps || 10000
    };
    this.used = {
      cpu: 0,
      memory: 0,
      requests: 0
    };
  }

  canAllocate(cpu, memory) {
    return (this.used.cpu + cpu) <= this.limits.cpuTotal &&
           (this.used.memory + memory) <= this.limits.memoryTotal;
  }

  allocate(cpu, memory) {
    if (this.canAllocate(cpu, memory)) {
      this.used.cpu += cpu;
      this.used.memory += memory;
      return true;
    }
    return false;
  }

  release(cpu, memory) {
    this.used.cpu = Math.max(0, this.used.cpu - cpu);
    this.used.memory = Math.max(0, this.used.memory - memory);
  }

  getUtilization() {
    return {
      cpu: ((this.used.cpu / this.limits.cpuTotal) * 100).toFixed(2) + '%',
      memory: ((this.used.memory / this.limits.memoryTotal) * 100).toFixed(2) + '%'
    };
  }
}

function generateId() {
  return crypto.randomBytes(6).toString('hex');
}

// Export
module.exports = {
  AutoScaler,
  HorizontalPodAutoscaler,
  ResourceQuota,
  createAutoScaler: (options) => new AutoScaler(options),
  createHPA: (deployment, metrics, options) => new HorizontalPodAutoscaler(deployment, metrics, options),
  createResourceQuota: (options) => new ResourceQuota(options)
};

