  }

  console.log('\n📊 Phase 6.3 Results:');
  console.log(`✅ Passed: ${passed}/5`);
  console.log(`❌ Failed: ${failed}/5\n`);

  return failed === 0;
}

// ──────────────────────────────────────────────────────────────────────────
// Main Test Runner
// ──────────────────────────────────────────────────────────────────────────

async function runAllTests() {
  console.log('\n╔════════════════════════════════════════════════════════╗');
  console.log('║  🧪 Phase 6: Advanced Features Integration Tests      ║');
  console.log('╚════════════════════════════════════════════════════════╝');

