// ============================================================================
// Integration Tests: Phase 6 Advanced Features
// ============================================================================

const { createAutoScaler, createResourceQuota } = require('./freelang/core/autoscaling');
const { createMesh, createTracer } = require('./freelang/core/service-mesh');
const { MetricsCollector, Dashboard } = require('./freelang/core/metrics-prometheus');

// ──────────────────────────────────────────────────────────────────────────
// Phase 6.1: Prometheus Metrics Tests
// ──────────────────────────────────────────────────────────────────────────

async function testPrometheus() {
  console.log('\n╔═══════════════════════════════════════════════════════╗');
  console.log('║  📊 Phase 6.1: Prometheus Metrics & Monitoring        ║');
  console.log('╚═══════════════════════════════════════════════════════╝\n');

  const collector = new MetricsCollector();
  let passed = 0;
  let failed = 0;

  // Test 1: HTTP Metrics Recording
  console.log('📝 Test 1: HTTP Metrics Recording');
  try {
    for (let i = 0; i < 20; i++) {
      collector.recordRequest('GET', i % 20 < 18 ? 200 : 500, Math.random() * 1000);
    }

    const dashboard = collector.getDashboard();
    if (dashboard.httpMetrics.totalRequests === 20) {
      console.log(`✅ Recorded 20 HTTP requests`);
      console.log(`   Success rate: ${dashboard.httpMetrics.successRate}`);
      passed++;
    } else {
      console.log('❌ Request recording failed');
      failed++;
    }
  } catch (err) {
    console.log('❌ Test 1 failed:', err.message);
    failed++;
  }

  // Test 2: Database Metrics
  console.log('\n📝 Test 2: Database Metrics');
  try {
    for (let i = 0; i < 10; i++) {
      collector.recordDatabaseOperation('INSERT', i < 9, Math.random() * 100);
    }

    const json = collector.exportJSON();
    if (json.metrics.database_operations_total.value === 10) {
      console.log(`✅ Recorded 10 DB operations`);
      console.log(`   Errors: ${json.metrics.database_errors_total.value}`);
      passed++;
    } else {
      console.log('❌ DB metrics failed');
      failed++;
    }
  } catch (err) {
    console.log('❌ Test 2 failed:', err.message);
    failed++;
  }

  // Test 3: Prometheus Format Export
  console.log('\n📝 Test 3: Prometheus Format Export');
  try {
    const prom = collector.exportPrometheus();
    if (prom.includes('http_requests_total') && prom.includes('TYPE counter')) {
      console.log(`✅ Prometheus format valid (${prom.split('\n').length} lines)`);
      passed++;
    } else {
      console.log('❌ Prometheus export failed');
      failed++;
    }
  } catch (err) {
    console.log('❌ Test 3 failed:', err.message);
    failed++;
  }

  // Test 4: Alert Detection
  console.log('\n📝 Test 4: Alert Detection');
  try {
    // Simulate many errors
    for (let i = 0; i < 15; i++) {
      collector.recordDatabaseOperation('UPDATE', false, 100);
    }

    const alerts = collector.checkAlerts();
    if (alerts.length > 0) {
      console.log(`✅ Alerts detected: ${alerts.length}`);
      alerts.forEach(a => console.log(`   [${a.severity}] ${a.message}`));
      passed++;
    } else {
      console.log('⚠️ No alerts triggered (may be normal)');
      passed++;
    }
  } catch (err) {
    console.log('❌ Test 4 failed:', err.message);
    failed++;
